svg.script:
const HAIR_ORIGIN =
  "M15.019 46.2552C3.0266 64.522 -9.92523 104.013 34.2069 115.844" +
  "C89.3722 130.633 92.9699 -1.73727 149.934 3.66188" +
  "C206.898 9.06103 227.285 88.2485 156.53 123.043" +
  "C85.7744 157.838 109.759 58.8532 149.934 66.6519" +
  "C190.109 74.4507 227.277 105.287 191.904 170.856" +
  "C156.53 236.425 228.301 221.905 227.493 186.572";

function buildPath(dx, dy) {
  var mx   = 15.019  + dx;
  var my   = 46.2552 + dy;
  var cp1x = 3.0266  + dx * 0.7;
  var cp1y = 64.522  + dy * 0.7;
  return (
    "M" + mx + " " + my +
    "C" + cp1x + " " + cp1y + " -9.92523 104.013 34.2069 115.844" +
    "C89.3722 130.633 92.9699 -1.73727 149.934 3.66188" +
    "C206.898 9.06103 227.285 88.2485 156.53 123.043" +
    "C85.7744 157.838 109.759 58.8532 149.934 66.6519" +
    "C190.109 74.4507 227.277 105.287 191.904 170.856" +
    "C156.53 236.425 228.301 221.905 227.493 186.572"
  );
}

var hr = document.getElementById('hr');

function startSnap() {
  var keyframes = [
    { t: 0,    dx: 0,   dy: 0   },
    { t: 0.45, dx: -28, dy: -20 },
    { t: 0.62, dx: 12,  dy: 8   },
    { t: 0.76, dx: -5,  dy: -4  },
    { t: 0.87, dx: 2,   dy: 2   },
    { t: 0.94, dx: -1,  dy: -1  },
    { t: 1.0,  dx: 0,   dy: 0   }
  ];

  var totalDuration = 1300;
  var startTime = performance.now();

  function lerp(a, b, t) { return a + (b - a) * t; }
  function easeInOut(t)  { return t < 0.5 ? 2*t*t : -1+(4-2*t)*t; }

  function tick(now) {
    var progress = Math.min((now - startTime) / totalDuration, 1);
    var dx = 0, dy = 0;
    for (var i = 0; i < keyframes.length - 1; i++) {
      var k0 = keyframes[i], k1 = keyframes[i + 1];
      if (progress >= k0.t && progress <= k1.t) {
        var e = easeInOut((progress - k0.t) / (k1.t - k0.t));
        dx = lerp(k0.dx, k1.dx, e);
        dy = lerp(k0.dy, k1.dy, e);
        break;
      }
    }
    hr.setAttribute('d', buildPath(dx, dy));
    if (progress < 1) {
      requestAnimationFrame(tick);
    } else {
      hr.setAttribute('d', HAIR_ORIGIN);
    }
  }
  requestAnimationFrame(tick);
}

// 머리카락 그리기 완료(2.9s + 0.85s = 3.75s) 후 튕김 실행
setTimeout(startSnap, 3750);
